// === Tab: baren ===
const makeBarenGfx = (bS) => {
  const barenBlack = 30;

  // Prepare baren gfx
  const gfx = createGraphics(width, height);
  gfx.fill(barenBlack);

  // First, draw black circle.
  gfx.circle(bS / 2, bS / 2, bS);

  // Prepare bT: barenTexture
  const bT = makeBarenTexture(bS);

  // Prepare bM: barenMask
  const bM = makeBarenMask(bS);

  // Clone texture and make image
  const bTClone = bT.get();
  bT.remove();

  // Mask the cloned image
  bTClone.mask(bM.get());
  bM.remove();

  // Draw final gfx
  gfx.image(bTClone, 0, 0);

  return gfx;
};

// Make Baren mask
const makeBarenMask = (bS) => {

  const vs = [];

  // For Octagon
  for (let i = 0; i < 8; i++) {
    const v = p5.Vector.fromAngle(TAU / 16 + (i * TAU) / 8);
    v.mult(bS / 2 + bS / 18);
    v.add(createVector(bS / 2, bS / 2));
    vs.push(v);
  }

  // Create mask gfx
  const gfx = createGraphics(width, height);
  gfx.strokeJoin(ROUND);
  // gfx.circle(bS / 2, bS / 2, bS);
  gfx.beginShape();
  vs.forEach((v) => {
    gfx.vertex(v.x, v.y);
  });
  gfx.endShape(CLOSE);

  return gfx;
};

// Make Baren texture rects
const makeBarenTexture = (bS) => {
  const barenColorLight = '#e9cc83';
  const barenColorDark = '#987d4d';

  const bT = createGraphics(width, height);
  bT.fill(barenColorLight);
  bT.noStroke();

  const vs = [];
  for (let i = 0; i < 8; i++) {
    const v = p5.Vector.fromAngle((i * TAU) / 8);
    v.mult(bS / 2 - bS / 18);
    v.add(createVector(bS / 2, bS / 2));
    vs.push(v);
  }

  bT.rectMode(CENTER);
  const bTRotateArray = [PI / 2, -PI / 4, 0, PI / 4, PI / 2, -PI / 4, 0, PI / 4];
  [2, 6, 1, 3, 5, 7, 0, 4].forEach((j) => {
    bT.push();
    {
      bT.translate(vs[j].x, vs[j].y);
      bT.rotate(bTRotateArray[j]);
      bT.rect(0, 0, bS / 2, bS / 8);

      const darkBarenColor = color(barenColorDark);
      darkBarenColor.setAlpha(255);
      bT.fill(darkBarenColor);

      for (let k = 0; k < 200; k++) {
        bT.ellipse(
          random(bS / 2) - bS / 4,
          random(bS / 8) - bS / 16,
          W / 100,
          (noise(k) * W) / 200
        );
      }
    }
    bT.pop();
  });

  bT.push();
  {
    bT.rect(bS / 2, bS / 2, bS, bS / 6);

    const darkBarenColor = color(barenColorDark);
    darkBarenColor.setAlpha(255);
    bT.fill(darkBarenColor);

    for (let k = 0; k < 600; k++) {
      bT.ellipse(
        random(bS) - bS / 2 + bS / 2,
        random(bS / 6) - bS / 12 + bS / 2,
        W / 100,
        (noise(k) * W) / 200
      );
    }
  }
  bT.pop();

  return bT;
};


