// === Tab: woodcut ===
const unit = 8;

class Woodcut {
  constructor(targetGfx, paperColor, inkColor) {

    const lines = [];

    const w = targetGfx.width;
    const h = targetGfx.height;
    const gfx = createGraphics(w, h);
    gfx.fill(paperColor); // '#f1e9db'
    gfx.noStroke();
    gfx.background(inkColor); // 30

    // For random matrix picking
    for (let i = 0; i < h / unit + 1; i++) {
      for (let j = 0; j < w / unit + 1; j++) {
        lines.push({ x: unit * j, y: unit * i });
      }
    }
    shuffle(lines, true);

    for (let i = 0; i < lines.length; i++) {
      const val = targetGfx.get(lines[i].x, lines[i].y)[0];
      if (val === 0) {
        gfx.push();
        {
          gfx.translate(lines[i].x, lines[i].y);
          gfx.rotate(random(-PI / 30, PI / 30));
          gfx.ellipse(0, 0, unit / random(1, 2), unit * random(1, 6));
        }
        gfx.pop();
      }
    }
    return gfx;
  }
}


