const W = 720;
const barenSize = W / 4;

const paperColor = '#f1e9db';
const inkColor = 30;

let pictGfx;
let maskGfx;
let barenGfx;
let barenEnable = true;

function setup() {
  createCanvas(W, W);
  pixelDensity(1);

  prepareTexture(width, height);

  barenGfx = makeBarenGfx(barenSize);

  maskGfx = createGraphics(width, height);
  maskGfx.background(paperColor);
  maskGfx.erase();

  const shapesGfx = makeShape();
  pictGfx = new Woodcut(shapesGfx, paperColor, inkColor);

  shapesGfx.remove();
}

function draw() {

  // Draw picture in bottom layer.
  image(pictGfx, 0, 0);

  // Update mask and Draw it. 
  if (barenEnable && ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    rub(maskGfx, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  }
  image(maskGfx, 0, 0);

  // Draw baren
  if (barenEnable) {
    image(barenGfx, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - barenSize / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - barenSize / 2);
  }

  // Draw texture
  image(textureGfx, 0, 0);
}

// Rub the mask
